mapper.select:
SELECT d.ID AS accept_detail_id, a.APPLY_NO AS accept_apply_no, d.PARTS_NO AS parts_no, d.PARTS_NAME AS parts_name, d.REMARK AS remark, d.UNIT_NAME AS unit_name, d.QUANTITY AS quantity, d.TOTAL_PRICE_RMB AS amount, a.ACCEPT_CATEGORY AS accept_category, a.STATUS AS accept_status, pc.SUPPLIER_NO AS supplier_no, pc.SUPPLIER_NAME AS supplier_name, a.PURCHASE_CONTRACT_NO AS contract_no, a.PURCHASE_CONTRACT_NAME AS contract_name, a.CREATE_TIME AS accept_date FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_purchase_contract pc ON a.PURCHASE_CONTRACT_NO = pc.APPLY_NO WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 1 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND NOT EXISTS ( SELECT 1 FROM tb_settlement_order s WHERE s.IS_DELETED = 0 AND s.STATUS >= 1 AND JSON_CONTAINS(s.ACCEPT_DETAIL_IDS, CAST(d.ID AS JSON)) )
AND pc.SUPPLIER_NO = #{supplierNo}
AND d.PARTS_NO LIKE CONCAT('%', #{partsNo}, '%')
AND d.PARTS_NAME LIKE CONCAT('%', #{partsName}, '%')
ORDER BY a.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT d.ID AS accept_detail_id, a.APPLY_NO AS accept_apply_no, d.PARTS_NO AS parts_no, d.PARTS_NAME AS parts_name, d.REMARK AS remark, d.UNIT_NAME AS unit_name, d.QUANTITY AS quantity, d.TOTAL_PRICE_RMB AS amount, a.ACCEPT_CATEGORY AS accept_category, a.STATUS AS accept_status, bc.SUPPLIER_NO AS supplier_no, bc.SUPPLIER_NAME AS supplier_name, a.BOM_PURCHASE_CONTRACT_NO AS contract_no, a.BOM_PURCHASE_CONTRACT_NAME AS contract_name, hp.END_TIME_ AS accept_date, a.PROCESS_INSTANCE_ID AS process_instance_id FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_bom_purchase_contract bc ON a.BOM_PURCHASE_CONTRACT_NO = bc.APPLY_NO LEFT JOIN `act_hi_procinst` hp ON a.PROCESS_INSTANCE_ID = hp.`PROC_INST_ID_` WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 2 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND NOT EXISTS ( SELECT 1 FROM tb_settlement_order s WHERE s.IS_DELETED = 0 AND s.STATUS >= 1 AND JSON_CONTAINS(s.ACCEPT_DETAIL_IDS, CAST(d.ID AS JSON)) )
AND bc.SUPPLIER_NO = #{supplierNo}
AND d.PARTS_NO LIKE CONCAT('%', #{partsNo}, '%')
AND d.PARTS_NAME LIKE CONCAT('%', #{partsName}, '%')
ORDER BY hp.END_TIME_ DESC LIMIT #{limit} OFFSET #{offset}

