INSERT INTO tb_settlement_order (
    SETTLEMENT_NO, supplier_no, supplier_name,
    INVOICE_AMOUNT, INVOICE_TAX_RATE, INVOICE_TAX_AMOUNT, INVOICE_TOTAL_AMOUNT,
    remark, STATUS, CREATE_USER, CREATE_DEPT, ACCEPT_DETAIL_IDS
) VALUES (
    #{settlementNo}, #{supplierNo}, #{supplierName},
    #{invoiceAmount}, #{invoiceTaxRate}, #{invoiceTaxAmount}, #{invoiceTotalAmount},
    #{remark}, 0, #{createUser}, #{createDept}, #{acceptDetailIds}
)

mapper.select:
SELECT s.ID AS id, s.SETTLEMENT_NO AS settlement_no, s.supplier_no AS supplier_no, c.SUPPLIER_NAME AS supplier_name, s.INVOICE_TOTAL_AMOUNT AS invoice_total_amount, s.STATUS AS status, s.CREATE_TIME AS create_time, GROUP_CONCAT(DISTINCT l.INVOICE_NO ORDER BY l.ID SEPARATOR ',') AS invoice_no, GROUP_CONCAT(DISTINCT l.INVOICE_DATE ORDER BY l.ID SEPARATOR ',') AS invoice_date FROM tb_settlement_order s LEFT JOIN tb_settlement_invoice_line l ON s.ID = l.SETTLEMENT_ID AND l.IS_DELETED = 0 LEFT JOIN tb_contract_supplier c ON s.supplier_no = c.SUPPLIER_NO AND c.IS_DELETED = 0 WHERE s.IS_DELETED = 0
AND s.supplier_no = #{supplierNo}
AND s.SETTLEMENT_NO LIKE CONCAT('%', #{settlementNo}, '%')
AND s.STATUS = #{status}
GROUP BY s.ID ORDER BY s.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM tb_settlement_order
WHERE IS_DELETED = 0

    AND supplier_no = #{supplierNo}

SELECT ID AS id, SETTLEMENT_NO AS settlementNo FROM tb_settlement_order WHERE IS_DELETED = 0 AND STATUS = 0 AND (
JSON_CONTAINS(ACCEPT_DETAIL_IDS, CAST(#{id} AS JSON))
)
